def type_to_dict(typ: type) ->TypeDict:
    if is_typed_dict(typ):
        return typed_dict_to_dict(typ)

    # Get module and qualname
    module = typ.__module__
    qualname = qualname_of_generic(typ) if is_generic(typ) else typ.__qualname__

    result: TypeDict = {
        "module": module,
        "qualname": qualname,
    }

    # Handle generic types with element types
    if is_generic(typ):
        # Get the origin type and its arguments
        origin = getattr(typ, '__origin__', None)
        args = getattr(typ, '__args__', None)
        if args:
            elem_types = [type_to_dict(arg) for arg in args]
            result["elem_types"] = elem_types

    return result
